"""Static scientific export, with real denominators and escaped source data."""
from html import escape
import json

def html_report(report):
    e=lambda x:escape(str(x));m=report['metrics']
    def dist(values):return '<table><thead><tr><th>Official source label</th><th>Count</th></tr></thead><tbody>'+''.join('<tr><td>'+e(k)+'</td><td>'+e(v)+'</td></tr>' for k,v in values.items())+'</tbody></table>'
    def ratio(v):return f"{v['numerator']} / {v['denominator']} ({v['percent']}%)" if v['denominator'] else 'Not determinable (denominator 0)'
    examples=''
    for example in report['examples']:
        comparisons=''
        for group in example['comparisons']:
            comparisons+='<p><b>'+e(group['condition_key'])+'</b> · '+e(group['bands'])+' · '+e(group['scv_count'])+' SCVs; '+e(group['submitters'])+' submitters.</p><p>RCVs: '+e(', '.join(group['rcvs']) or 'No exact RCV condition mapping')+'</p>'
        rows=''.join('<tr><td><a href="'+e(s['url'])+'">'+e(s['accession'])+'</a></td><td>'+e(s['submitter'])+'</td><td>'+e(s['classification'])+'</td><td>'+e(s['review_status'])+'</td><td>'+e(s['last_evaluated'] or 'missing')+'</td><td>'+e(s['contributes_to_aggregate'])+'</td></tr>' for s in example['scvs'])
        examples+='<article><p class="label">OBSERVED DATA / COMPUTATIONAL COMPARISON</p><h3><a href="'+e(example['url'])+'">'+e(example['vcv'])+'</a></h3><p>'+e(example['name'])+'</p><p>Official VCV aggregate: '+e(example['aggregate']['description'])+' · '+e(example['aggregate']['review_status'])+'</p>'+comparisons+'<div class="table"><table><thead><tr><th>SCV</th><th>Submitter</th><th>Classification</th><th>Review</th><th>Evaluation</th><th>Contributes</th></tr></thead><tbody>'+rows+'</tbody></table></div></article>'
    sources=''.join('<tr><td><a href="'+e(s['url'])+'">'+e(s['organization'])+'</a></td><td>'+e(s['acquired_at'])+'</td><td>'+e(s.get('release_date') or 'API response; see accession versions')+'</td><td><code>'+e(s['sha256'])+'</code></td><td>'+e(s.get('record_counts'))+'</td></tr>' for s in report.get('sources',[]))
    findings=''.join('<article><p class="label">'+e(f['kind'])+'</p><h3>'+e(f['title'])+'</h3><p>'+e(f['method'])+'</p><pre>'+e(json.dumps(f['result'],ensure_ascii=False,indent=2))+'</pre><p>'+e(f['limits'])+'</p></article>' for f in report['findings'])
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>Research Engines · GEE-001</title><style>
body{font:16px/1.75 system-ui,sans-serif;color:#182026;background:#f5f3ee;max-width:1180px;margin:0 auto;padding:48px 24px}h1{font-size:clamp(38px,6vw,72px);line-height:1.08;letter-spacing:-.05em;font-weight:500}h2{margin-top:52px;letter-spacing:-.03em}a{color:#315e72}.label{font:11px/1.8 monospace;letter-spacing:.15em}.stats{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid #ccd1d1;border-radius:16px;overflow:hidden}.stats>div{padding:25px}.stats b{display:block;font-size:32px}.stats span{font-size:12px;color:#56646a}article{background:#fffefa;border:1px solid #d5d9d7;border-radius:14px;padding:24px;margin:20px 0}table{border-collapse:collapse;width:100%;font-size:12px}td,th{text-align:left;padding:12px 10px;border-bottom:1px solid #d5d9d7;vertical-align:top}code{overflow-wrap:anywhere}td code{font-size:10px}.table{overflow-x:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.notice{border-left:3px solid #9c7b46;padding-left:20px}.sources td{max-width:280px}footer{border-top:1px solid #ccd1d1;padding-top:25px;margin-top:45px;color:#56646a;font-size:13px}@media(max-width:700px){.stats{grid-template-columns:1fr 1fr}body{padding:24px 18px}}@media print{article{break-inside:avoid}body{padding:10px}}
</style></head><body><header><p class="label">MATTOCCIA LABS / RESEARCH ENGINES / ENGINE 02</p><h1>Genomics Evidence Engine.<br>Experiment GEE-001.</h1><p>Classificatory discordance in public BRCA1/BRCA2 variant evidence.</p></header>'''+ '<p class="notice">Experimental research only. Not a diagnostic system, medical advice or a clinical reassessment. Public variant-level data attributed to NCBI ClinVar and Ensembl; original software Apache-2.0. No personal genetic data, patient observations or AI-generated numeric results.</p><p>Acquired: '+e(report.get('completed_at',''))+' · method '+e(report['method_version'])+' · analysis SHA256 <code>'+e(report['analysis_sha256'])+'</code></p><div class="stats">'+''.join('<div><b>'+e(v)+'</b><span>'+e(k)+'</span></div>' for k,v in [('Unique variants',m['variants']),('Condition records / RCV',m['rcv_records']),('Germline submissions / SCV',m['current_germline_scv_records']),('Unique submitter IDs',m['unique_submitters'])])+'</div><h2>Selection and denominators</h2><pre>'+e(json.dumps(report['selection'],ensure_ascii=False,indent=2))+'</pre><p>This is a deterministic lowest-ID sample, not a random sample or estimate of all BRCA variants. RCVs and SCVs are not counted as variants. Scope excludes nonclassified/haplotype/nonhuman/other-gene records with reasons retained below.</p><h2>1 / Quantitative results</h2><p>Official aggregate germline conflict: <b>'+e(ratio(m['official_aggregate_conflicts']))+'</b>. Same-condition cross-band SCV difference: <b>'+e(ratio(m['same_condition_differences']))+'</b> of variants with at least one comparable condition group.</p>'+dist(m['classification_distribution'])+'<h2>2 / Documented examples</h2>'+(examples or '<p>No eligible discordance example found under the documented criteria; no invented example substituted.</p>')+'<h2>3 / Documentary completeness</h2>'+dist(m['review_status_distribution'])+'<p>SCVs with declared criteria: '+e(ratio(m['scv_criteria_declared']))+'; evaluation date: '+e(ratio(m['scv_with_evaluation_date']))+'; citation identifiers: '+e(ratio(m['scv_with_citations']))+'. These are metadata availability indicators, not scientific reliability scores.</p><p>Expert-panel VCVs: '+e(ratio(m['expert_panel_aggregate']))+'. Submitter organization categories below are SCV-weighted, denominator '+e(m['current_germline_scv_records'])+' submissions, not unique organizations.</p>'+dist(m['submitter_categories_scv_weighted'])+'<h3>Distinct submitter organizations</h3><p>Organization IDs deduplicated across the study; denominator '+e(m['unique_submitters'])+' organizations. A combined label is retained if source categories differ.</p>'+dist(m['submitter_categories_unique_organizations'])+'<h2>Cross-source annotation</h2><p>Exact GRCh38 SNV match to Ensembl VEP: '+e(ratio(m['variants_with_ensembl_annotation']))+' attempted compatible variants. Predicted molecular consequence is independent of the clinical classification.</p><pre>'+e(json.dumps(report.get('ensembl_summary',{}),ensure_ascii=False,indent=2))+'</pre><h2>Research findings</h2>'+findings+'<h2>Excluded/invalid records and acquisition errors</h2><pre>'+e(json.dumps({'exclusions':report.get('exclusions',{}),'errors':report.get('errors',[])},ensure_ascii=False,indent=2))+'</pre><h2>Scientific limits</h2><ul>'+''.join('<li>'+e(x)+'</li>' for x in report['limitations'])+'</ul><h2>Sources and reproducibility manifest</h2><p>Each SHA256 refers to a complete cached API response, not the whole ClinVar database. Prefix probes of large TSV files are recorded separately and are not full-file checksums. API record versions are preserved; a common release timestamp is not assumed.</p><div class="table sources"><table><thead><tr><th>Official source URL</th><th>Acquisition UTC</th><th>Release/date metadata</th><th>Full response SHA256</th><th>Record counts</th></tr></thead><tbody>'+sources+'</tbody></table></div><footer>NCBI ClinVar data source: <a href="https://www.ncbi.nlm.nih.gov/clinvar/docs/maintenance_use/">data-use policy and attribution</a>. Ensembl: <a href="https://www.ensembl.org/about/articles/ensembl-content-disclaimer">data reuse terms</a>. No endorsement by NCBI/NIH, EMBL-EBI or submitters implied. Results do not modify the source classifications.</footer></body></html>'
